    VALUES ('55555555-9776-0000-0000-000000000001', 'dc000008-0000-0000-0000-000000000008', 0, 'Nexora Brand Personality, Tone, and Voice Standards: Brand Personality: Nexora is strictly defined as professional, trustworthy, helpful, and approachable. Tone and Voice: Our communication voice must be consistently respectful, confident, clear, and customer-focused across all marketing copy, sales documents, and public statements. Writing Style: Communicate with formality and precision. Avoid confusing technical jargon, ungrounded superlatives, and passive bureaucratic phrasing. Always prioritize actionable, clear, and direct explanations.', 1, '[-0.023542,0.000000,-0.028372,-0.010463,0.018110,0.027365,0.002415,-0.138840,-0.010866,-0.001610,0.000402,-0.014689,-0.001610,0.014890,0.034811,0.023341,0.016299,-0.014689,0.000000,-0.037225,0.001610,-0.008049,0.060767,-0.025756,0.112078,-0.012073,0.019518,0.021329,0.003622,-0.021530,0.037829,-0.024750,0.049701,-0.015494,-0.062780,0.000000,0.043463,0.024548,0.008854,0.028975,0.002213,-0.013280,0.020122,-0.039640,-0.010262,-0.017103,0.008451,-0.024146,0.043262,-0.001409,-0.009658,-0.015292,0.000000,-0.011671,-0.001610,0.014488,0.011872,-0.015896,0.014689,0.022737,0.019518,-0.011872,0.015695,-0.016299,-0.024951,-0.038634,-0.025152,0.000402,-0.011067,0.000000,-0.015695,0.014890,-0.034609,-0.014488,0.010866,0.001610,-0.013280,0.004829,-0.007646,-0.009256,0.025555,0.008451,0.055536,0.019317,-0.011469,-0.070828,0.000000,0.035615,0.019719,-0.008049,-0.001811,-0.023341,0.006037,0.014488,-0.013079,-0.006841,0.013884,-0.017103,0.021329,0.020725,-0.018311,0.004024,-0.031591,0.000000,-0.037829,-0.041853,0.009256,0.011067,0.010664,0.002415,-0.023542,-0.003823,0.007244,0.013280,-0.017103,-0.013482,-0.010866,0.022536,0.024146,-0.040646,0.000000,-0.040847,-0.037829,-0.003018,-0.010664,-0.014488,-0.007244,-0.027567,0.010664,0.015695,-0.001610,-0.021530,-0.004226,0.014085,0.001610,0.020524,-0.047487,0.000000,0.009256,-0.047085,0.032396,-0.052719,